    if (problem) {
      setError(problem);
      return;
    }

    setSaving(true);
    try {
      setSuccess(await onChangePassword(current, next));
      setCurrent('');
      setNext('');
      setConfirmation('');
    } catch (err) {
      setError(apiErrorMessage(err, 'Não foi possível trocar a senha.'));
    } finally {
      setSaving(false);
    }
  };

  return (
