import React, { useEffect, useState } from 'react';
import type { AccountUser, ProfileChanges } from '../../hooks/useAccount';
import { apiErrorMessage } from '../../utils/apiError';
import { formatPhone, validateAvatarUrl, validateFullName, validatePhone } from '../../utils/profileValidation';
import styles from './Account.module.css';

type Props = {
  user: AccountUser;
  onSave: (changes: ProfileChanges) => Promise<unknown>;
};

/** Campos alterados em relação ao usuário salvo, já no formato do backend. */
export function profileChanges(
  user: AccountUser,
  form: { fullName: string; phone: string; avatarUrl: string },
): ProfileChanges {
  const changes: ProfileChanges = {};
  const fullName = form.fullName.trim();
  const phone = formatPhone(form.phone) || null;
  const avatarUrl = form.avatarUrl.trim() || null;
  if (fullName !== user.full_name) changes.full_name = fullName;
  if (phone !== user.phone) changes.phone = phone;
  if (avatarUrl !== user.avatar_url) changes.avatar_url = avatarUrl;
  return changes;
}

const ProfileForm = ({ user, onSave }: Props) => {
  const [fullName, setFullName] = useState(user.full_name);
  const [phone, setPhone] = useState(user.phone ?? '');
  const [avatarUrl, setAvatarUrl] = useState(user.avatar_url ?? '');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [saving, setSaving] = useState(false);

  // Depois de salvar, mostra o que o backend gravou (o telefone volta normalizado).
  useEffect(() => {
    setFullName(user.full_name);
    setPhone(user.phone ?? '');
    setAvatarUrl(user.avatar_url ?? '');
  }, [user]);

  const handleSubmit = async (event: React.FormEvent) => {
    event.preventDefault();
    setError('');
    setSuccess('');

    const problem = validateFullName(fullName) ?? validatePhone(phone) ?? validateAvatarUrl(avatarUrl);
    if (problem) {
      setError(problem);
      return;
    }
    const changes = profileChanges(user, { fullName, phone, avatarUrl });
    if (Object.keys(changes).length === 0) {
      setSuccess('Nada mudou desde o último salvamento.');
      return;
    }

    setSaving(true);
    try {
      await onSave(changes);
      setSuccess('Dados salvos.');
    } catch (err) {
      setError(apiErrorMessage(err, 'Não foi possível salvar seus dados.'));
    } finally {
      setSaving(false);
    }
  };

  return (
    <form className={styles.card} onSubmit={handleSubmit} noValidate aria-labelledby="perfil-titulo">
      <h2 id="perfil-titulo">Dados pessoais</h2>

      <div className={styles.field}>
        <label htmlFor="perfil-nome">Nome</label>
        <input
          id="perfil-nome"
          value={fullName}
          onChange={(e) => setFullName(e.target.value)}
          autoComplete="name"
          maxLength={255}
        />
      </div>

      <div className={styles.field}>
        <label htmlFor="perfil-telefone">Telefone</label>
        <input
          id="perfil-telefone"
          type="tel"
          value={phone}
          onChange={(e) => setPhone(e.target.value)}
          autoComplete="tel-national"
          placeholder="(91) 99999-0000"
        />
        <span className={styles.hint}>Com DDD. Deixe em branco para remover.</span>
      </div>

      <div className={styles.field}>
        <label htmlFor="perfil-foto">URL da foto</label>
        <input
          id="perfil-foto"
          type="url"
          value={avatarUrl}
          onChange={(e) => setAvatarUrl(e.target.value)}
          placeholder="https://"
        />
      </div>

      {error && <p className={styles.error} role="alert">{error}</p>}
      {success && <p className={styles.success} role="status">{success}</p>}

      <div className={styles.actions}>
        <button type="submit" className={styles.submit} disabled={saving}>
          {saving ? 'Salvando...' : 'Salvar dados'}
        </button>
      </div>
    </form>
  );
};

export default ProfileForm;

import React, { useState } from 'react';
import { apiErrorMessage } from '../../utils/apiError';
import { validateNewPassword } from '../../utils/profileValidation';
import styles from './Account.module.css';

type Props = {
  /** Troca a senha e devolve a mensagem de confirmação. */
  onChangePassword: *** string, newPassword: ***) => Promise<string>;
};

const PasswordForm = ({ onChangePassword }: Props) => {
  const [current, setCurrent] = useState('');
  const [next, setNext] = useState('');
  const [confirmation, setConfirmation] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [saving, setSaving] = useState(false);

  const handleSubmit = async (event: React.FormEvent) => {
    event.preventDefault();
    setError('');
    setSuccess('');

    const problem = validateNewPassword(current, next, confirmation);
    if (problem) {
      setError(problem);
      return;
    }

    setSaving(true);
    try {
      setSuccess(await onChangePassword(current, next));
      setCurrent('');
      setNext('');
      setConfirmation('');
    } catch (err) {
      setError(apiErrorMessage(err, 'Não foi possível trocar a senha.'));
    } finally {
      setSaving(false);
    }
  };

  return (
    <form className={styles.card} onSubmit={handleSubmit} noValidate aria-labelledby="senha-titulo">
      <h2 id="senha-titulo">Trocar senha</h2>

      <div className={styles.field}>
        <label htmlFor="senha-atual">Senha atual</label>
        <input
          id="senha-atual"
          type="password"
          value={current}
          onChange={(e) => setCurrent(e.target.value)}
          autoComplete="current-password"
        />
      </div>

      <div className={styles.field}>
        <label htmlFor="senha-nova">Nova senha</label>
        <input
          id="senha-nova"
          type="password"
          value={next}
          onChange={(e) => setNext(e.target.value)}
          autoComplete="new-password"
        />
        <span className={styles.hint}>No mínimo 8 caracteres, com pelo menos 1 letra e 1 número.</span>
      </div>

      <div className={styles.field}>
        <label htmlFor="senha-confirmacao">Confirme a nova senha</label>
        <input
          id="senha-confirmacao"
          type="password"
          value={confirmation}
          onChange={(e) => setConfirmation(e.target.value)}
          autoComplete="new-password"
        />
      </div>

      {error && <p className={styles.error} role="alert">{error}</p>}
      {success && <p className={styles.success} role="status">{success}</p>}

      <div className={styles.actions}>
        <button type="submit" className={styles.submit} disabled={saving}>
          {saving ? 'Trocando...' : 'Trocar senha'}
        </button>
      </div>
    </form>
  );
};

export default PasswordForm;

