import { afterEach, describe, expect, it, vi } from 'vitest';
import PasswordForm from './PasswordForm';

// SPEC/2026-11-22-auth-perfil-senha.md: formulário de troca de senha da página "Minha conta".

const SUCCESS = 'Senha alterada. As outras sessões foram encerradas.';

function http400(detail: string): AxiosError {
  const config = { headers: {} } as InternalAxiosRequestConfig;
  const response = { status: 400, data: { detail }, statusText: '', headers: {}, config } as AxiosResponse;
  return new AxiosError('HTTP 400', AxiosError.ERR_BAD_REQUEST, config, null, response);
}

function fill(current: string, next: string, confirmation = next) {
  fireEvent.change(screen.getByLabelText('Senha atual'), { target: { value: current } });
  fireEvent.change(screen.getByLabelText('Nova senha'), { target: { value: next } });
  fireEvent.change(screen.getByLabelText('Confirme a nova senha'), { target: { value: confirmation } });
  fireEvent.click(screen.getByRole('button', { name: 'Trocar senha' }));
}

const valueOf = (label: string) => (screen.getByLabelText(label) as HTMLInputElement).value;

afterEach(cleanup);

describe('PasswordForm', () => {
  it('troca a senha, mostra a confirmação do backend e limpa os campos', async () => {
    const onChangePassword = ***).mockResolvedValue(SUCCESS);
    render(<PasswordForm onChangePassword=***} />);

    fill('senhaAtual1', 'senhaNova2');

    expect(await screen.findByRole('status')).toHaveProperty('textContent', SUCCESS);
    expect(onChangePassword).toHaveBeenCalledWith('senhaAtual1', 'senhaNova2');
    expect([valueOf('Senha atual'), valueOf('Nova senha'), valueOf('Confirme a nova senha')]).toEqual(['', '', '']);
  });

  it.each([
    ['', 'senhaNova2', 'senhaNova2', 'Informe a senha atual'],
    ['senhaAtual1', 'curta1', 'curta1', 'Nova senha deve ter no mínimo 8 caracteres'],
    ['senhaAtual1', 'senhaAtual1', 'senhaAtual1', 'A nova senha precisa ser diferente da atual.'],
    ['senhaAtual1', 'senhaNova2', 'senhaNova3', 'A confirmação não é igual à nova senha'],
  ])('atual=%j nova=%j confirmação=%j: mostra o erro e não envia', async (current, next, confirmation, message) => {
    const onChangePassword = ***);
    render(<PasswordForm onChangePassword=***} />);

    fill(current, next, confirmation);

    expect(await screen.findByRole('alert')).toHaveProperty('textContent', message);
    expect(onChangePassword).not.toHaveBeenCalled();
  });

  it('senha atual errada: mostra o erro do backend e mantém os campos', async () => {
    const onChangePassword = ***).mockRejectedValue(http400('Senha atual incorreta.'));
    render(<PasswordForm onChangePassword=***} />);

    fill('senhaErrada9', 'senhaNova2');

    expect(await screen.findByRole('alert')).toHaveProperty('textContent', 'Senha atual incorreta.');
    expect(valueOf('Nova senha')).toBe('senhaNova2');
    expect(screen.queryByRole('status')).toBeNull();
  });

  it('os campos são de senha e têm o autocomplete certo', () => {
    render(<PasswordForm onChangePassword=***)} />);

    expect(screen.getByLabelText('Senha atual').getAttribute('type')).toBe('password');
    expect(screen.getByLabelText('Senha atual').getAttribute('autocomplete')).toBe('current-password');
    expect(screen.getByLabelText('Nova senha').getAttribute('autocomplete')).toBe('new-password');
  });
});

// @vitest-environment jsdom
import { cleanup, fireEvent, render, screen } from '@testing-library/react';
import { AxiosError, type AxiosResponse, type InternalAxiosRequestConfig } from 'axios';
import { MemoryRouter, Route, Routes } from 'react-router-dom';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import api from '../api';
import Account from './Account';

// SPEC/2026-11-22-auth-perfil-senha.md: a página carrega o /auth/me e usa as duas rotas novas.

vi.mock('../api', () => ({ default: { get: vi.fn(), put: vi.fn() } }));
const mocked = api as unknown as { get: ReturnType<typeof vi.fn>; put: ReturnType<typeof vi.fn> };

const USER = {
  id: '1',
  email: '***',
  full_name: 'maria',
  phone: null,
  avatar_url: null,
  role: 'client',
  email_verified: false,
};

function httpError(status: number): AxiosError {
  const config = { headers: {} } as InternalAxiosRequestConfig;
  const response = { status, data: {}, statusText: '', headers: {}, config } as AxiosResponse;
  return new AxiosError(`HTTP ${status}`, AxiosError.ERR_BAD_REQUEST, config, null, response);
}

function renderAccount() {
  return render(
    <MemoryRouter initialEntries={['/conta']}>
      <Routes>
        <Route path="/conta" element={<Account loginPath="/login" />} />
        <Route path="/login" element={<p>Tela de login</p>} />
      </Routes>
    </MemoryRouter>,
  );
}

beforeEach(() => {
  mocked.get.mockReset();
  mocked.put.mockReset();
});

afterEach(cleanup);

describe('Account', () => {
  it('mostra os dados do usuário, o perfil e o aviso de e-mail não verificado', async () => {
    mocked.get.mockResolvedValue({ data: USER });

    renderAccount();

    expect(await screen.findByRole('heading', { name: 'Minha conta' })).toBeTruthy();
    expect(screen.getByText('*** · Cliente')).toBeTruthy();
    expect(screen.getByText('Seu e-mail ainda não foi verificado.')).toBeTruthy();
    expect(screen.getByText('M')).toBeTruthy();
    expect(mocked.get).toHaveBeenCalledWith('/auth/me');
  });

  it.each([401, 403])('sem sessão (%i), manda para o login', async (status) => {
    mocked.get.mockRejectedValue(httpError(status));

    renderAccount();

    expect(await screen.findByText('Tela de login')).toBeTruthy();
  });

  it('outros erros aparecem na tela', async () => {
    mocked.get.mockRejectedValue(httpError(500));

    renderAccount();

    expect(await screen.findByRole('alert')).toHaveProperty('textContent', 'Não foi possível carregar seus dados.');
  });

  it('salva o perfil pelo PUT /auth/me e mostra o telefone como o backend gravou', async () => {
    mocked.get.mockResolvedValue({ data: USER });
    mocked.put.mockResolvedValue({ data: { ...USER, phone: '(91) 99999-0000' } });
    renderAccount();

    fireEvent.change(await screen.findByLabelText('Telefone'), { target: { value: '91 99999 0000' } });
    fireEvent.click(screen.getByRole('button', { name: 'Salvar dados' }));

    expect(await screen.findByText('Dados salvos.')).toBeTruthy();
    expect(mocked.put).toHaveBeenCalledWith('/auth/me', { phone: '(91) 99999-0000' });
    expect(screen.getByLabelText('Telefone')).toHaveProperty('value', '(91) 99999-0000');
  });

  it('troca a senha pelo PUT /auth/me/password', async () => {
    mocked.get.mockResolvedValue({ data: USER });
    mocked.put.mockResolvedValue({ data: { message: 'Senha alterada. As outras sessões foram encerradas.' } });
    renderAccount();

    fireEvent.change(await screen.findByLabelText('Senha atual'), { target: { value: 'senhaAtual1' } });
    fireEvent.change(screen.getByLabelText('Nova senha'), { target: { value: 'senhaNova2' } });
    fireEvent.change(screen.getByLabelText('Confirme a nova senha'), { target: { value: 'senhaNova2' } });
    fireEvent.click(screen.getByRole('button', { name: 'Trocar senha' }));

    expect(await screen.findByText('Senha alterada. As outras sessões foram encerradas.')).toBeTruthy();
    expect(mocked.put).toHaveBeenCalledWith('/auth/me/password', {
      current_password: '***',
      new_password: '***',
    });
  });
});

